// Q1612 — tuningFamilySocraticRadarMinkowskiP3Mean
export function tuningFamilySocraticRadarMinkowskiP3Mean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let total = 0, count = 0;
  for (let i = 0; i < vecs.length; i++) {
    for (let j = i + 1; j < vecs.length; j++) {
      const a = vecs[i]!;
      const b = vecs[j]!;
      let sum = 0;
      for (let k = 0; k < a.length; k++) {
        sum += Math.abs(a[k]! - b[k]!) ** 3;
      }
      total += sum ** (1 / 3);
      count++;
    }
  }
  return count === 0 ? 0 : total / count;
}

// Q1614 — tuningFamilySocraticRadarDegreeCentralityMean
export function tuningFamilySocraticRadarDegreeCentralityMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const adj: boolean[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3)
  );
  let total = 0;
  for (let i = 0; i < n; i++) {
    const degree = adj[i]!.filter(Boolean).length;
    total += degree / (n - 1);
  }
  return total / n;
}

// Q1616 — tuningFamilySocraticRadarClosenessCentralityMean
export function tuningFamilySocraticRadarClosenessCentralityMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const adj: boolean[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3)
  );
  let totalCloseness = 0;
  for (let src = 0; src < n; src++) {
    const dist = new Array<number>(n).fill(Infinity);
    dist[src] = 0;
    const queue = [src];
    let qi = 0;
    while (qi < queue.length) {
      const cur = queue[qi++]!;
      for (let nb = 0; nb < n; nb++) {
        if (adj[cur]![nb] && dist[nb] === Infinity) {
          dist[nb] = dist[cur]! + 1;
          queue.push(nb);
        }
      }
    }
    let sumDist = 0;
    let reachable = 0;
    for (let i = 0; i < n; i++) {
      if (i !== src && dist[i] !== Infinity) {
        sumDist += dist[i]!;
        reachable++;
      }
    }
    totalCloseness += reachable === 0 ? 0 : (n - 1) / sumDist;
  }
  return totalCloseness / n;
}

// Q1618 — tuningFamilySocraticRadarBetweennessCentralityMean
export function tuningFamilySocraticRadarBetweennessCentralityMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 2) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const adj: boolean[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3)
  );
  const betweenness = new Array<number>(n).fill(0);
  for (let s = 0; s < n; s++) {
    const dist = new Array<number>(n).fill(-1);
    const sigma = new Array<number>(n).fill(0);
    const pred: number[][] = Array.from({length: n}, () => []);
    dist[s] = 0;
    sigma[s] = 1;
    const queue = [s];
    const stack: number[] = [];
    let qi = 0;
    while (qi < queue.length) {
      const v = queue[qi++]!;
      stack.push(v);
      for (let w = 0; w < n; w++) {
        if (!adj[v]![w]) continue;
        if (dist[w] === -1) {
          dist[w] = dist[v]! + 1;
          queue.push(w);
        }
        if (dist[w] === dist[v]! + 1) {
          sigma[w] = (sigma[w] ?? 0) + sigma[v]!;
          pred[w]!.push(v);
        }
      }
    }
    const delta = new Array<number>(n).fill(0);
    while (stack.length > 0) {
      const w = stack.pop()!;
      for (const v of pred[w]!) {
        delta[v] = (delta[v] ?? 0) + (sigma[v]! / sigma[w]!) * (1 + delta[w]!);
      }
      if (w !== s) betweenness[w] = (betweenness[w] ?? 0) + delta[w]!;
    }
  }
  const norm = (n - 1) * (n - 2) / 2;
  let total = 0;
  for (let i = 0; i < n; i++) total += betweenness[i]! / norm;
  return total / n;
}

// Q1620 — tuningFamilySocraticRadarClusteringCoefficientMeanV2
export function tuningFamilySocraticRadarClusteringCoefficientMeanV2(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 2) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const adj: boolean[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3)
  );
  let totalCC = 0;
  for (let i = 0; i < n; i++) {
    const neighbors: number[] = [];
    for (let j = 0; j < n; j++) {
      if (adj[i]![j]) neighbors.push(j);
    }
    const k = neighbors.length;
    if (k < 2) { totalCC += 0; continue; }
    let triangles = 0;
    for (let a = 0; a < neighbors.length; a++) {
      for (let b = a + 1; b < neighbors.length; b++) {
        if (adj[neighbors[a]!]![neighbors[b]!]) triangles++;
      }
    }
    totalCC += (triangles * 2) / (k * (k - 1));
  }
  return totalCC / n;
}

// Q1622 — tuningFamilySocraticRadarGraphDensityMean
export function tuningFamilySocraticRadarGraphDensityMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 2) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const adj: boolean[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3)
  );
  const groupSize = 3;
  let totalDensity = 0;
  let groupCount = 0;
  for (let start = 0; start < n; start += groupSize) {
    const group: number[] = [];
    for (let gi = start; gi < Math.min(start + groupSize, n); gi++) group.push(gi);
    const m = group.length;
    const possible = m * (m - 1) / 2;
    if (possible === 0) { groupCount++; totalDensity += 0; continue; }
    let edges = 0;
    for (let a = 0; a < group.length; a++) {
      for (let b = a + 1; b < group.length; b++) {
        if (adj[group[a]!]![group[b]!]) edges++;
      }
    }
    totalDensity += edges / possible;
    groupCount++;
  }
  return groupCount === 0 ? 0 : totalDensity / groupCount;
}

// Q1624 — tuningFamilySocraticRadarSpectralRadiusMean
export function tuningFamilySocraticRadarSpectralRadiusMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const euclidean = (a: number[], b: number[]): number =>
    Math.sqrt(a.reduce((s, v, k) => s + (v - b[k]!) * (v - b[k]!), 0));
  const A: number[][] = Array.from({length: n}, (_, i) =>
    Array.from({length: n}, (__, j) => (i !== j && euclidean(vecs[i]!, vecs[j]!) < 0.3) ? 1 : 0)
  );
  let vec = new Array<number>(n).fill(1 / Math.sqrt(n));
  let eigenvalue = 0;
  for (let iter = 0; iter < 10; iter++) {
    const next = new Array<number>(n).fill(0);
    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        next[i] = (next[i] ?? 0) + A[i]![j]! * vec[j]!;
      }
    }
    eigenvalue = Math.sqrt(next.reduce((s, v) => s + v * v, 0));
    if (eigenvalue === 0) break;
    vec = next.map((v) => v / eigenvalue);
  }
  return eigenvalue / n;
}

// Q1626 — tuningFamilySocraticRadarErgodicityScore
export function tuningFamilySocraticRadarErgodicityScore(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const k = axes.length;
  // ensemble average = mean over all tunings × all axes
  let total = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < k; j++) total += vecs[i]![j]!;
  const ensembleAvg = total / (n * k);
  if (ensembleAvg === 0) return 0;
  // time average per tuning = mean of 5 axes
  let sumDiff = 0;
  for (let i = 0; i < n; i++) {
    const timeAvg = vecs[i]!.reduce((s, v) => s + v, 0) / k;
    sumDiff += Math.abs(timeAvg - ensembleAvg);
  }
  const score = 1 - sumDiff / n / ensembleAvg;
  return Math.max(0, Math.min(1, score));
}

// Q1628 — tuningFamilySocraticRadarMixingCoefficient
export function tuningFamilySocraticRadarMixingCoefficient(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const k = axes.length;
  let totalAutocorr = 0;
  for (let j = 0; j < k; j++) {
    // sort tuning profiles by their j-th axis value
    const sorted = [...vecs].sort((a, b) => a[j]! - b[j]!).map((v) => v[j]!);
    let num = 0;
    let denom = 0;
    for (let i = 0; i < sorted.length - 1; i++) {
      num += sorted[i]! * sorted[i + 1]!;
      denom += sorted[i]! * sorted[i]!;
    }
    const autocorr = denom === 0 ? 0 : num / denom - 1;
    totalAutocorr += Math.abs(autocorr);
  }
  void n;
  const meanAutocorr = totalAutocorr / k;
  return Math.max(0, Math.min(1, 1 - meanAutocorr));
}

// Q1630 — tuningFamilySocraticRadarLyapunovExponentProxy
export function tuningFamilySocraticRadarLyapunovExponentProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  let totalLogDiv = 0;
  let count = 0;
  for (let i = 0; i < n - 1; i++) {
    const vi = vecs[i]!;
    const vi1 = vecs[i + 1]!;
    let dist = 0;
    for (let j = 0; j < vi.length; j++) dist += (vi1[j]! - vi[j]!) * (vi1[j]! - vi[j]!);
    dist = Math.sqrt(dist);
    totalLogDiv += Math.log(dist + 1e-10);
    count++;
  }
  return count === 0 ? 0 : totalLogDiv / count;
}

// Q1632 — tuningFamilySocraticRadarRecurrenceRateMean
export function tuningFamilySocraticRadarRecurrenceRateMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  let recurrences = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      // Chebyshev distance
      let maxDiff = 0;
      for (let kk = 0; kk < vecs[i]!.length; kk++) {
        const diff = Math.abs(vecs[i]![kk]! - vecs[j]![kk]!);
        if (diff > maxDiff) maxDiff = diff;
      }
      if (maxDiff < 0.1) recurrences++;
    }
  }
  return recurrences / (n * (n - 1));
}

// Q1634 — tuningFamilySocraticRadarInvariantMeasureEntropy
export function tuningFamilySocraticRadarInvariantMeasureEntropy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const bins = new Array<number>(10).fill(0);
  let total = 0;
  for (const vec of vecs) {
    for (const v of vec) {
      const binIdx = Math.min(9, Math.floor(v * 10));
      bins[binIdx]!++;
      total++;
    }
  }
  if (total === 0) return 0;
  let entropy = 0;
  for (const b of bins) {
    if (b === 0) continue;
    const p = b / total;
    entropy -= p * Math.log(p);
  }
  return entropy;
}

// Q1636 — tuningFamilySocraticRadarCorrelationDimensionProxy
export function tuningFamilySocraticRadarCorrelationDimensionProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const n = vecs.length;
  const r = 0.2;
  let pairs = 0;
  let totalPairs = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      let dist = 0;
      for (let kk = 0; kk < vecs[i]!.length; kk++) {
        const d = vecs[i]![kk]! - vecs[j]![kk]!;
        dist += d * d;
      }
      dist = Math.sqrt(dist);
      if (dist < r) pairs++;
      totalPairs++;
    }
  }
  if (totalPairs === 0) return 0;
  const cr = pairs / totalPairs;
  if (cr === 0) return 0;
  return Math.max(0, Math.log(cr) / Math.log(r));
}

// Q1638 — tuningFamilySocraticRadarComplexityIndexMean
export function tuningFamilySocraticRadarComplexityIndexMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    const total = vec.reduce((a, b) => a + b, 0);
    const norm = total > 0 ? vec.map((v) => v / total) : vec.map(() => 1 / 5);
    let H = 0;
    for (const p of norm) {
      H -= p * Math.log2(p + 1e-10);
    }
    let D = 0;
    for (const p of norm) {
      const d = p - 1 / 5;
      D += d * d;
    }
    sum += H * D;
  }
  return sum / tunings.length;
}

// Q1640 — tuningFamilySocraticRadarEmergenceMean
export function tuningFamilySocraticRadarEmergenceMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    const mean = vec.reduce((a, b) => a + b, 0) / n;
    let variance = 0;
    for (const v of vec) {
      variance += (v - mean) * (v - mean);
    }
    variance /= n;
    const std = Math.sqrt(variance);
    const maxVal = Math.max(...vec);
    const emergence = Math.max(0, std / (maxVal + 1e-10));
    sum += emergence;
  }
  return sum / tunings.length;
}

