// Q1744 — tuningFamilySocraticRadarExpansionConstantMean
export function tuningFamilySocraticRadarExpansionConstantMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    // Try all subsets S of size 1..floor(n/2): approximate min(|boundary|/|S|)
    let minExpansion = Infinity;
    const maxSubsetSize = Math.floor(n / 2);
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j <= i + maxSubsetSize; j++) {
        const inS = new Set<number>();
        for (let k = i; k < j; k++) inS.add(k % n);
        let boundary = 0;
        for (const idx of inS) {
          const left = (idx - 1 + n) % n;
          const right = (idx + 1) % n;
          if (!inS.has(left)) boundary++;
          if (!inS.has(right)) boundary++;
        }
        const expansion = boundary / inS.size;
        if (expansion < minExpansion) minExpansion = expansion;
      }
    }
    // In a ring of 5, singleton expansion = 2, pair = 2, so normalize by 2
    const normalized = Number.isFinite(minExpansion) ? Math.min(minExpansion / 2, 1) : 0;
    sum += normalized;
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1746 — tuningFamilySocraticRadarKolmogorovComplexityProxy
export function tuningFamilySocraticRadarKolmogorovComplexityProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    // Discretize each axis value to 3 levels: <1/3→0, <2/3→1, ≥2/3→2
    const discrete = vec.map((v) => (v < 1 / 3 ? 0 : v < 2 / 3 ? 1 : 2));
    // Run-length encoding length
    let rleLen = 0;
    let i = 0;
    while (i < discrete.length) {
      rleLen++;
      const cur = discrete[i]!;
      while (i < discrete.length && discrete[i]! === cur) i++;
    }
    // Normalize by 5 (max RLE length = number of axes) and clamp
    sum += Math.min(rleLen / 5, 1);
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1748 — tuningFamilySocraticRadarLempelZivComplexityProxy
export function tuningFamilySocraticRadarLempelZivComplexityProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    // Discretize to 10 levels
    const discrete = vec.map((v) => Math.min(9, Math.floor(v * 10)));
    // LZ76 algorithm: parse sequence into distinct phrases
    const phrases = new Set<string>();
    let start = 0;
    let end = 1;
    while (end <= discrete.length) {
      const substr = discrete.slice(start, end).join(',');
      if (!phrases.has(substr)) {
        phrases.add(substr);
        start = end;
      }
      end++;
    }
    const numPhrases = phrases.size;
    // Normalize by 5 and clamp
    sum += Math.min(numPhrases / 5, 1);
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1750 — tuningFamilySocraticRadarApproximateEntropyProxy
export function tuningFamilySocraticRadarApproximateEntropyProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps = 1e-10;
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    const r = 0.2; // tolerance
    // Count template matches for m=2 and m=3
    const countMatches = (m: number): number => {
      let count = 0;
      for (let i = 0; i <= n - m; i++) {
        for (let j = 0; j <= n - m; j++) {
          let match = true;
          for (let k = 0; k < m; k++) {
            if (Math.abs(vec[i + k]! - vec[j + k]!) > r) {
              match = false;
              break;
            }
          }
          if (match) count++;
        }
      }
      return count;
    };
    const cm2 = countMatches(2);
    const cm3 = countMatches(3);
    const denom2 = n - 1 > 0 ? n - 1 : 1;
    const denom3 = n - 2 > 0 ? n - 2 : 1;
    const phi2 = Math.log(Math.max(cm2, eps) / denom2);
    const phi3 = Math.log(Math.max(cm3, eps) / denom3);
    const apen = phi2 - phi3;
    // Normalize by ln(n) and clamp
    const maxApen = Math.log(n + eps);
    sum += Math.max(0, Math.min(1, apen / maxApen));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1752 — tuningFamilySocraticRadarSampleEntropyProxy
export function tuningFamilySocraticRadarSampleEntropyProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps = 1e-10;
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    const r = 0.2;
    // Count template matches excluding self-matches for m=2 and m+1=3
    const countMatchesNoSelf = (m: number): number => {
      let count = 0;
      for (let i = 0; i <= n - m; i++) {
        for (let j = 0; j <= n - m; j++) {
          if (i === j) continue; // exclude self-matches
          let match = true;
          for (let k = 0; k < m; k++) {
            if (Math.abs(vec[i + k]! - vec[j + k]!) > r) {
              match = false;
              break;
            }
          }
          if (match) count++;
        }
      }
      return count;
    };
    const A = countMatchesNoSelf(3); // m+1=3 matches
    const B = countMatchesNoSelf(2); // m=2 matches
    const samp = -Math.log(Math.max(A, eps) / Math.max(B, eps));
    // Normalize by ln(n) and clamp
    const maxSamp = Math.log(n + eps);
    sum += Math.max(0, Math.min(1, samp / maxSamp));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1754 — tuningFamilySocraticRadarPermutationEntropyProxy
export function tuningFamilySocraticRadarPermutationEntropyProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps = 1e-10;
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    const m = 3; // ordinal pattern length
    // Enumerate ordinal patterns (permutations of order-3 windows)
    const patternCounts = new Map<string, number>();
    let total = 0;
    for (let i = 0; i <= n - m; i++) {
      const window = Array.from({ length: m }, (_, k) => vec[i + k]!);
      // Get ordinal pattern: sort indices by value
      const indices = Array.from({ length: m }, (_, k) => k);
      indices.sort((a, b) => window[a]! - window[b]!);
      const pattern = indices.join(',');
      patternCounts.set(pattern, (patternCounts.get(pattern) ?? 0) + 1);
      total++;
    }
    // Shannon entropy of pattern distribution
    let entropy = 0;
    for (const cnt of patternCounts.values()) {
      const p = cnt / Math.max(total, 1);
      entropy -= p * Math.log2(Math.max(p, eps));
    }
    // Normalize by log2(m!) = log2(6) for m=3
    const maxEntropy = Math.log2(6);
    sum += Math.max(0, Math.min(1, entropy / maxEntropy));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1756 — tuningFamilySocraticRadarMultiscaleEntropyProxy
export function tuningFamilySocraticRadarMultiscaleEntropyProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps = 1e-10;

  const sampleEntropyVec = (vec: number[]): number => {
    const n = vec.length;
    const r = 0.2;
    let A = 0;
    let B = 0;
    for (let i = 0; i < n - 2; i++) {
      for (let j = 0; j < n - 2; j++) {
        if (i === j) continue;
        const match2 =
          Math.abs(vec[i]! - vec[j]!) <= r && Math.abs(vec[i + 1]! - vec[j + 1]!) <= r;
        if (match2) {
          B++;
          if (Math.abs(vec[i + 2]! - vec[j + 2]!) <= r) A++;
        }
      }
    }
    return -Math.log(Math.max(A, eps) / Math.max(B, eps));
  };

  let sum = 0;
  for (const vec of vecs) {
    // Scale 1: original
    const se1 = sampleEntropyVec(vec);
    // Scale 2: coarse-grain by averaging pairs
    const coarse: number[] = [];
    for (let i = 0; i + 1 < vec.length; i += 2) {
      coarse.push((vec[i]! + vec[i + 1]!) / 2);
    }
    const se2 = coarse.length >= 3 ? sampleEntropyVec(coarse) : se1;
    const meanSe = (se1 + se2) / 2;
    // Normalize by ln(n), clamp to [0,1]
    const maxSe = Math.log(vec.length + eps);
    sum += Math.max(0, Math.min(1, meanSe / maxSe));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1758 — tuningFamilySocraticRadarFractalDimensionProxyV2
export function tuningFamilySocraticRadarFractalDimensionProxyV2(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  void spectrum;
  void rootHz;
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps1 = 0.1;
  const eps2 = 0.25;
  let sum = 0;
  for (const vec of vecs) {
    const countBoxes = (eps: number): number => {
      const boxes = new Set<number>();
      for (const v of vec) {
        boxes.add(Math.floor(v / eps));
      }
      return boxes.size;
    };
    const n1 = countBoxes(eps1);
    const n2 = countBoxes(eps2);
    const d = n2 > 0 && n1 > 0 ? Math.log(n1 / n2) / Math.log(eps2 / eps1) : 0;
    const normalized = Math.max(0, Math.min(1, d / 2));
    sum += normalized;
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1760 — tuningFamilySocraticRadarSelfSimilarityRatioMean
export function tuningFamilySocraticRadarSelfSimilarityRatioMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    if (n < 2) {
      sum += 0;
      continue;
    }
    // first 3 axes vs last 3 axes: correlation as self-similarity proxy
    const half = Math.floor(n / 2);
    const a = vec.slice(0, half);
    const b = vec.slice(n - half);
    const meanA = a.reduce((s, v) => s + v, 0) / half;
    const meanB = b.reduce((s, v) => s + v, 0) / half;
    let num = 0;
    let da = 0;
    let db = 0;
    for (let i = 0; i < half; i++) {
      const ai = a[i]! - meanA;
      const bi = b[i]! - meanB;
      num += ai * bi;
      da += ai * ai;
      db += bi * bi;
    }
    const denom = Math.sqrt(da * db);
    const corr = denom > 0 ? num / denom : 0;
    // map correlation from [-1,1] to [0,1]
    sum += Math.max(0, Math.min(1, (corr + 1) / 2));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1762 — tuningFamilySocraticRadarLacunarityProxy
export function tuningFamilySocraticRadarLacunarityProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    if (n === 0) {
      sum += 0;
      continue;
    }
    const mean = vec.reduce((s, v) => s + v, 0) / n;
    const variance = vec.reduce((s, v) => s + (v - mean) * (v - mean), 0) / n;
    const lacunarity = mean > 0 ? variance / (mean * mean) : 0;
    // normalize via v/(v+1)
    sum += lacunarity / (lacunarity + 1);
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1764 — tuningFamilySocraticRadarHolderExponentMean
export function tuningFamilySocraticRadarHolderExponentMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  const eps = 0.2;
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    if (n < 2) {
      sum += 0;
      continue;
    }
    let holderSum = 0;
    for (let i = 1; i < n; i++) {
      holderSum += Math.abs(vec[i]! - vec[i - 1]!) / eps;
    }
    const meanHolder = holderSum / (n - 1);
    // normalize to [0,1] by clamping
    sum += Math.max(0, Math.min(1, meanHolder));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1766 — tuningFamilySocraticRadarMultifractalSpectrumWidth
export function tuningFamilySocraticRadarMultifractalSpectrumWidth(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  let sum = 0;
  for (const vec of vecs) {
    if (vec.length === 0) {
      sum += 0;
      continue;
    }
    const maxVal = Math.max(...vec);
    const minVal = Math.min(...vec);
    // width in [0,1] naturally since axes are in [0,1]
    sum += Math.max(0, Math.min(1, maxVal - minVal));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1768 — tuningFamilySocraticRadarIteratedFunctionProxy
export function tuningFamilySocraticRadarIteratedFunctionProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  // contraction f(x) = 0.5*x + 0.25, fixed point = 0.5
  const fixedPoint = 0.5;
  let sum = 0;
  for (const vec of vecs) {
    const n = vec.length;
    if (n === 0) {
      sum += 0;
      continue;
    }
    let axisDev = 0;
    for (const v of vec) {
      let x = v;
      // iterate 3 times
      x = 0.5 * x + 0.25;
      x = 0.5 * x + 0.25;
      x = 0.5 * x + 0.25;
      axisDev += Math.abs(x - fixedPoint);
    }
    const meanDev = axisDev / n;
    // normalize to [0,1]: max possible dev after 3 iter is 0.5^3 * |v - fixed_point| <= 0.125
    sum += Math.max(0, Math.min(1, meanDev / 0.125));
  }
  const avg = sum / tunings.length;
  return Math.max(0, Math.min(1, avg));
}

// Q1770 — tuningFamilySocraticRadarNashEquilibriumProxyV2
export function tuningFamilySocraticRadarNashEquilibriumProxyV2(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  // For each axis, find which profile has the maximum value (axis-wise maximum position).
  // Count axes where only one profile is the unique maximum (consensus maximum).
  let consensusCount = 0;
  for (let axIdx = 0; axIdx < axes.length; axIdx++) {
    const axVals = vecs.map((v) => v[axIdx]!);
    const maxVal = Math.max(...axVals);
    const maxProfiles = axVals.filter((v) => v === maxVal).length;
    // consensus: only one profile is the unique maximum
    if (maxProfiles === 1) consensusCount++;
  }
  const proportion = consensusCount / axes.length;
  return Math.max(0, Math.min(1, proportion));
}

// Q1772 — tuningFamilySocraticRadarCooperationIndexMean
export function tuningFamilySocraticRadarCooperationIndexMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) {
    // single profile: cooperation with itself = 1
    return 1;
  }
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const p = vecs[i]!;
    const q = vecs[i + 1]!;
    let sumMin = 0;
    let sumMax = 0;
    for (let k = 0; k < axes.length; k++) {
      sumMin += Math.min(p[k]!, q[k]!);
      sumMax += Math.max(p[k]!, q[k]!);
    }
    const coop = sumMax === 0 ? 1 : sumMin / sumMax;
    total += coop;
    pairs++;
  }
  const avg = pairs === 0 ? 0 : total / pairs;
  return Math.max(0, Math.min(1, avg));
}

// Q1774 — tuningFamilySocraticRadarCompetitionIndexMean
export function tuningFamilySocraticRadarCompetitionIndexMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  return 1 - tuningFamilySocraticRadarCooperationIndexMean(tunings, spectrum, rootHz);
}

// Q1776 — tuningFamilySocraticRadarParetoDominanceMean
export function tuningFamilySocraticRadarParetoDominanceMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) return 0;
  const nAxes = axes.length;
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const p = vecs[i]!;
    const q = vecs[i + 1]!;
    // count axes where p dominates q (p_i > q_i)
    let domCount = 0;
    for (let k = 0; k < nAxes; k++) {
      if (p[k]! > q[k]!) domCount++;
    }
    total += domCount / nAxes;
    pairs++;
  }
  const avg = pairs === 0 ? 0 : total / pairs;
  return Math.max(0, Math.min(1, avg));
}

// Q1778 — tuningFamilySocraticRadarShapleyValueProxy
export function tuningFamilySocraticRadarShapleyValueProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  const n = tunings.length;
  if (n === 0) return 0;
  if (n <= 1) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  // mean profile across all tunings
  const meanAll = axes.map((_, axIdx) => {
    let s = 0;
    for (const v of vecs) s += v[axIdx]!;
    return s / n;
  });
  // marginal contribution of each tuning: mean absolute change in mean profile when removed
  let totalMarginal = 0;
  for (let i = 0; i < n; i++) {
    const removed = vecs[i]!;
    let marginalSum = 0;
    for (let axIdx = 0; axIdx < axes.length; axIdx++) {
      const meanWithout = (meanAll[axIdx]! * n - removed[axIdx]!) / (n - 1);
      marginalSum += Math.abs(meanAll[axIdx]! - meanWithout);
    }
    totalMarginal += marginalSum / axes.length;
  }
  const meanMarginal = totalMarginal / n;
  // normalize to [0,1]: max possible marginal is 1 (axis value range is [0,1])
  return Math.max(0, Math.min(1, meanMarginal));
}

// Q1780 — tuningFamilySocraticRadarMinimaxProxy
export function tuningFamilySocraticRadarMinimaxProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  // for each profile, compute max over axes; then take min over profiles
  const profileMaxes = vecs.map((v) => Math.max(...v));
  const minimaxVal = Math.min(...profileMaxes);
  return Math.max(0, Math.min(1, minimaxVal));
}

// Q1782 — tuningFamilySocraticRadarMorphismCountProxy
export function tuningFamilySocraticRadarMorphismCountProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) {
    // single profile: normalize rank count by 5! = 120
    return Math.max(0, Math.min(1, 1 / 120));
  }
  // factorial of 5
  const fact5 = 120;
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const a = vecs[i]!;
    const b = vecs[i + 1]!;
    // count monotone maps: pairs (j,k) where a[j] <= a[k] implies b[j] <= b[k]
    let monotone = 0;
    for (let j = 0; j < axes.length; j++) {
      for (let k = j + 1; k < axes.length; k++) {
        if (a[j]! <= a[k]! && b[j]! <= b[k]!) monotone++;
        if (a[j]! >= a[k]! && b[j]! >= b[k]!) monotone++;
      }
    }
    total += monotone / fact5;
    pairs++;
  }
  return Math.max(0, Math.min(1, total / pairs));
}

// Q1784 — tuningFamilySocraticRadarFunctorFaithfulnessProxy
export function tuningFamilySocraticRadarFunctorFaithfulnessProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) {
    // single profile: rank correlation with itself is 1
    return Math.max(0, Math.min(1, 1));
  }
  const rank = (arr: number[]): number[] => {
    const sorted = [...arr].sort((a, b) => a - b);
    return arr.map((v) => sorted.indexOf(v));
  };
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const ra = rank(vecs[i]!);
    const rb = rank(vecs[i + 1]!);
    const n = ra.length;
    const meanA = ra.reduce((s, v) => s + v, 0) / n;
    const meanB = rb.reduce((s, v) => s + v, 0) / n;
    let num = 0, da = 0, db = 0;
    for (let j = 0; j < n; j++) {
      const a = ra[j]! - meanA;
      const b = rb[j]! - meanB;
      num += a * b;
      da += a * a;
      db += b * b;
    }
    const corr = da === 0 || db === 0 ? 0 : num / Math.sqrt(da * db);
    total += (corr + 1) / 2; // map [-1,1] -> [0,1]
    pairs++;
  }
  return Math.max(0, Math.min(1, total / pairs));
}

// Q1786 — tuningFamilySocraticRadarNaturalTransformationMean
export function tuningFamilySocraticRadarNaturalTransformationMean(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) {
    return 0;
  }
  const norm = Math.sqrt(axes.length); // sqrt(5)
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const a = vecs[i]!;
    const b = vecs[i + 1]!;
    let dist = 0;
    for (let j = 0; j < axes.length; j++) {
      dist += Math.abs(a[j]! - b[j]!);
    }
    total += dist / norm;
    pairs++;
  }
  // invert: closer profiles → higher faithfulness
  const meanDist = total / pairs;
  return Math.max(0, Math.min(1, 1 - meanDist));
}

// Q1788 — tuningFamilySocraticRadarAdjunctionProxy
export function tuningFamilySocraticRadarAdjunctionProxy(
  tunings: readonly TuningSystem[],
  spectrum: Spectrum,
  rootHz?: number,
): number {
  type AxisKey = 'diversity' | 'versatility' | 'maturity' | 'benchmark' | 'convergence';
  const axes: AxisKey[] = ['diversity', 'versatility', 'maturity', 'benchmark', 'convergence'];
  if (tunings.length === 0) return 0;
  const profiles = tunings.map((t) => tuningFamilySocraticRadarProfile([t], spectrum, rootHz));
  const vecs = profiles.map((p) => axes.map((ax) => p[ax]));
  if (vecs.length < 2) {
    return 0;
  }
  let total = 0;
  let pairs = 0;
  for (let i = 0; i < vecs.length - 1; i++) {
    const q = vecs[i + 1]!;
    // count axes where p[ai] <= q[j] for all j (left adjoint indicator)
    let count = 0;
    for (let ai = 0; ai < axes.length; ai++) {
      const allLeq = q.every((qj) => vecs[i]![ai]! <= qj);
      if (allLeq) count++;
    }
    total += count / axes.length;
    pairs++;
  }
  return Math.max(0, Math.min(1, total / pairs));
}

